'use client'

import { cn, useSignal, useSignalEffect, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { useRef } from 'react'
import type { KeyboardEvent, ReactNode } from 'react'
import styles from './reorder-list.module.css'

export interface ReorderItem {
  id: string
  label: ReactNode
  /** Plain-text name used in announcements when `label` is not a string. */
  name?: string
}

/** Placeholder set every announcement string — built-in or overridden — is filled with. */
interface Announcement {
  name: string
  position: number
  total: number
}

export interface ReorderListProps {
  value: ReorderItem[]
  onValueChange: (value: ReorderItem[]) => void
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
  labels?: {
    handle?: string
    grabbed?: string
    moved?: string
    dropped?: string
    cancelled?: string
  }
  className?: string
}

/** Announcement text needs a plain string; fall back to the id for non-string labels. */
function nameOf(item: ReorderItem): string {
  return item.name ?? (typeof item.label === 'string' ? item.label : item.id)
}

function move(items: ReorderItem[], from: number, to: number): ReorderItem[] {
  const next = items.slice()
  const [moved] = next.splice(from, 1)
  if (moved) next.splice(to, 0, moved)
  return next
}

/**
 * A list whose rows can be reordered by pointer drag or entirely by keyboard.
 *
 * Each row carries a drag handle. Space or Enter picks the row up, Arrow keys move it,
 * Space or Enter drops it, and Escape restores the order it had before the pick-up — the
 * keyboard path Ionic's pointer-only `ion-reorder` has no equivalent for. Every transition
 * is announced through a polite live region.
 */
export function ReorderList({
  value,
  onValueChange,
  disabled = false,
  labels,
  className,
}: ReorderListProps) {
  useSignals()
  const listRef = useRef<HTMLUListElement>(null)
  /** Index of the row currently held, by keyboard or by pointer. */
  const activeIndex = useSignal<number | null>(null)
  const announcement = useSignal('')

  // Read at callback time (pointer/keyboard handlers), never to drive effect re-runs.
  const valueRef = useRef(value)
  valueRef.current = value
  const onValueChangeRef = useRef(onValueChange)
  onValueChangeRef.current = onValueChange
  const disabledRef = useRef(disabled)
  disabledRef.current = disabled
  /** Order captured at pick-up, so Escape can restore it. */
  const orderBeforeGrab = useRef<ReorderItem[] | null>(null)

  /**
   * Announce an override if the caller supplied one, else the already-resolved catalog
   * string. Overrides are interpolated here against the same placeholder set, so a custom
   * label supports `{name}`, `{position}` and `{total}` exactly as the built-in does.
   */
  const announce = (override: string | undefined, resolved: string, params: Announcement): void => {
    announcement.value = override
      ? override
          .replace('{name}', params.name)
          .replace('{position}', String(params.position))
          .replace('{total}', String(params.total))
      : resolved
  }

  const reorder = (from: number, to: number): void => {
    const items = valueRef.current
    const clamped = Math.max(0, Math.min(items.length - 1, to))
    if (clamped === from) return
    const item = items[from]
    if (!item) return
    onValueChangeRef.current(move(items, from, clamped))
    activeIndex.value = clamped
    const params = { name: nameOf(item), position: clamped + 1, total: items.length }
    announce(labels?.moved, t(builtin.reorderList.moved, params), params)
  }

  const grab = (index: number): void => {
    const items = valueRef.current
    const item = items[index]
    if (!item) return
    orderBeforeGrab.current = items
    activeIndex.value = index
    const params = { name: nameOf(item), position: index + 1, total: items.length }
    announce(labels?.grabbed, t(builtin.reorderList.grabbed, params), params)
  }

  const drop = (): void => {
    const index = activeIndex.value
    if (index === null) return
    const items = valueRef.current
    const item = items[index]
    orderBeforeGrab.current = null
    activeIndex.value = null
    if (!item) return
    const params = { name: nameOf(item), position: index + 1, total: items.length }
    announce(labels?.dropped, t(builtin.reorderList.dropped, params), params)
  }

  const cancel = (): void => {
    const original = orderBeforeGrab.current
    const index = activeIndex.value
    orderBeforeGrab.current = null
    activeIndex.value = null
    if (!original) return
    onValueChangeRef.current(original)
    const item = index === null ? undefined : original[index]
    const params = {
      name: item ? nameOf(item) : '',
      position: (index ?? 0) + 1,
      total: original.length,
    }
    announce(labels?.cancelled, t(builtin.reorderList.cancelled, params), params)
  }

  const onHandleKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number): void => {
    if (disabled) return
    const held = activeIndex.value
    if (event.key === ' ' || event.key === 'Enter') {
      event.preventDefault()
      if (held === index) drop()
      else grab(index)
      return
    }
    if (event.key === 'Escape' && held !== null) {
      event.preventDefault()
      cancel()
      return
    }
    if (held !== index) return
    if (event.key === 'ArrowUp') {
      event.preventDefault()
      reorder(index, index - 1)
    } else if (event.key === 'ArrowDown') {
      event.preventDefault()
      reorder(index, index + 1)
    }
  }

  // Pointer drag: rows reflow live as the pointer crosses their midpoints, so there is
  // no ghost element to keep in sync with the list.
  useSignalEffect(() => {
    const list = listRef.current
    if (!list || typeof window === 'undefined') return

    const onMove = (event: PointerEvent): void => {
      const from = activeIndex.value
      if (from === null || disabledRef.current) return
      const rows = [...list.querySelectorAll<HTMLElement>('[data-reorder-row]')]
      const target = rows.findIndex((row) => {
        const rect = row.getBoundingClientRect()
        return event.clientY >= rect.top && event.clientY <= rect.bottom
      })
      if (target !== -1 && target !== from) reorder(from, target)
    }
    const onUp = (): void => {
      if (activeIndex.value !== null && orderBeforeGrab.current) drop()
    }

    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
    window.addEventListener('pointercancel', onUp)
    return () => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
      window.removeEventListener('pointercancel', onUp)
    }
  })

  return (
    <div className={cn(styles['root'], className)}>
      <ul ref={listRef} className={styles['list']}>
        {value.map((item, index) => (
          <li
            key={item.id}
            data-reorder-row=""
            data-active={activeIndex.value === index ? '' : undefined}
            className={styles['row']}
          >
            <button
              type="button"
              disabled={disabled}
              aria-label={
                labels?.handle
                  ? labels.handle.replace('{name}', nameOf(item))
                  : t(builtin.reorderList.handle, { name: nameOf(item) })
              }
              aria-pressed={activeIndex.value === index}
              className={styles['handle']}
              onKeyDown={(event) => onHandleKeyDown(event, index)}
              onPointerDown={() => {
                if (!disabled) grab(index)
              }}
            >
              <svg aria-hidden="true" viewBox="0 0 16 16" className={styles['grip']}>
                <path
                  d="M6 4h.01M10 4h.01M6 8h.01M10 8h.01M6 12h.01M10 12h.01"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                />
              </svg>
            </button>
            <span className={styles['label']}>{item.label}</span>
          </li>
        ))}
      </ul>
      <span role="status" aria-live="polite" className={styles['srOnly']}>
        {announcement.value}
      </span>
    </div>
  )
}

@layer cascivo.component {
  /* Positioned so the visually-hidden live region anchors here rather than to some
     arbitrary ancestor of the consumer's. */
  .root {
    position: relative;
  }

  .list {
    display: flex;
    flex-direction: column;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .row {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    padding-inline: var(--cascivo-space-2);
    padding-block: var(--cascivo-space-2);
    border-block-end: 1px solid var(--cascivo-border-subtle);
    background: var(--cascivo-color-surface);

    &:last-child {
      border-block-end: none;
    }

    &[data-active] {
      background: var(--cascivo-color-surface-2);
    }
  }

  .handle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    padding: var(--cascivo-space-1);
    border: none;
    border-radius: var(--cascivo-radius-sm);
    background: transparent;
    color: var(--cascivo-color-text-muted);
    /* The handle owns the gesture; without this the browser scrolls instead. */
    touch-action: none;
    cursor: grab;

    &:focus-visible {
      outline: var(--cascivo-ring-width) solid var(--cascivo-ring-color);
      outline-offset: 2px;
    }

    &[aria-pressed='true'] {
      color: var(--cascivo-color-accent-text);
      cursor: grabbing;
    }

    &:disabled {
      opacity: var(--cascivo-disabled-opacity);
      cursor: not-allowed;
    }

    @media (pointer: coarse) {
      min-inline-size: var(--cascivo-target-min-coarse, 2.75rem);
      min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    }
  }

  .grip {
    inline-size: 1rem;
    block-size: 1rem;
  }

  .label {
    min-inline-size: 0;
    color: var(--cascivo-color-foreground);
  }

  .srOnly {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    padding: 0;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'ReorderList',
  description: 'List whose rows can be reordered by pointer drag or entirely by keyboard',
  category: 'inputs',
  clientJs: 'required',
  states: ['idle', 'grabbed', 'disabled'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'value',
      type: 'ReorderItem[]',
      required: true,
      description: 'The ordered items; the component is controlled',
    },
    {
      name: 'onValueChange',
      type: '(value: ReorderItem[]) => void',
      required: true,
      description: 'Called with the new order whenever a row moves',
    },
    {
      name: 'disabled',
      type: 'boolean',
      required: false,
      default: 'false',
      description: 'When true, disables the control and removes it from the tab order.',
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: '{ handle?: string; grabbed?: string; moved?: string; dropped?: string; cancelled?: string }',
      required: false,
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  typeDefs: [
    {
      name: 'ReorderItem',
      fields: [
        { name: 'id', type: 'string', required: true, description: 'Stable identity for the row' },
        {
          name: 'label',
          type: 'React.ReactNode',
          required: true,
          description: 'Row content',
        },
        {
          name: 'name',
          type: 'string',
          required: false,
          description: 'Plain-text name used in announcements when label is not a string',
        },
      ],
    },
  ],
  tokens: [
    '--cascivo-color-accent-text',
    '--cascivo-color-surface',
    '--cascivo-color-surface-2',
    '--cascivo-color-foreground',
    '--cascivo-color-text-muted',
    '--cascivo-border-subtle',
    '--cascivo-radius-sm',
    '--cascivo-ring-width',
    '--cascivo-ring-color',
    '--cascivo-disabled-opacity',
    '--cascivo-target-min-coarse',
  ],
  accessibility: {
    role: 'list',
    wcag: '2.2-AA',
    keyboard: ['Space', 'Enter', 'ArrowUp', 'ArrowDown', 'Escape', 'Tab'],
  },
  examples: [
    {
      title: 'Basic',
      code: `<ReorderList
  value={items}
  onValueChange={setItems}
/>`,
      description: 'Controlled — the caller owns the order.',
    },
    {
      title: 'Locked',
      code: `<ReorderList value={items} onValueChange={setItems} disabled />`,
      description: 'Handles are disabled and drop out of the tab order.',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['inputs', 'reorder', 'sortable', 'drag', 'list', 'mobile', 'keyboard'],
  intent: {
    whenToUse: [
      'A short, user-owned ordering such as playlist tracks, form fields, or dashboard cards',
      'Any list whose order is meaningful data the user is expected to change',
      'Touch surfaces where dragging a handle is the natural gesture',
    ],
    whenNotToUse: [
      'Long or virtualized lists, where dragging to a far position is impractical — offer a "move to position" control',
      'Ordering that is derived rather than authored (sort by name, date, rank) — use a sortable DataTable',
      'Read-only lists — use List or StructuredList',
    ],
    antiPatterns: [
      {
        bad: 'Rendering a drag handle with no keyboard path',
        good: 'Keep the built-in handle, which is a real button with Space/Arrow/Escape support',
        why: 'Pointer-only reordering is unusable by keyboard and screen-reader users; it is the standing accessibility gap in pointer-only implementations',
      },
      {
        bad: 'Deriving row keys from array index',
        good: 'Give every item a stable `id`',
        why: 'Index keys make React reuse the wrong DOM nodes as rows move, so focus and animation land on the wrong row',
      },
    ],
    related: [
      {
        name: 'List',
        relationship: 'alternative',
        reason: 'Plain list when the order is not user-editable',
      },
      {
        name: 'DataTable',
        relationship: 'alternative',
        reason: 'Column sorting when the order is derived rather than authored',
      },
      {
        name: 'SwipeItem',
        relationship: 'pairs-with',
        reason: 'Row-level swipe actions on the same touch list',
      },
    ],
    a11yRationale:
      'Every row carries a real button as its drag handle, so the entire interaction is reachable by keyboard: Space or Enter picks a row up, ArrowUp/ArrowDown move it, Space or Enter drops it, and Escape restores the order captured at pick-up. The handle exposes aria-pressed so assistive technology can tell held from idle, and each transition — picked up, moved, dropped, cancelled — is announced through a polite role="status" region using interpolated catalog strings that carry the item name and its position out of the total. The handle sets touch-action: none so a touch drag is not stolen by the scroller, and meets the coarse-pointer target floor. Item names for announcements come from `name` when the label is not plain text, so a rich label never produces an empty announcement.',
    flexibility: [
      {
        area: 'value / onValueChange',
        level: 'strict',
        note: 'Always controlled — the component never holds the order itself',
      },
      {
        area: 'labels',
        level: 'flexible',
        note: 'Every announcement string is overridable and supports {name}, {position} and {total}',
      },
      {
        area: 'handle',
        level: 'strict',
        note: 'The handle is always a focusable button; there is no drag-anywhere mode',
      },
    ],
  },
}
